const listProspects = `-- name: ListProspects :many
SELECT p.id, p.company_id, p.display_name, p.domain, p.status, p.source_key, p.data_quality, p.latest_score, p.latest_coverage, p.crm_company_id, p.owner_user_id, p.created_at, p.updated_at
FROM lead_generation.prospects p
WHERE p.tenant_id = $1 AND p.deleted_at IS NULL
  AND ($2::text IS NULL OR p.status = $2::text)
  AND ($3::int IS NULL OR p.latest_score >= $3::int)
  AND ($4::uuid IS NULL OR EXISTS (SELECT 1 FROM lead_generation.prospect_list_members m WHERE m.tenant_id = p.tenant_id AND m.list_id = $4::uuid AND m.prospect_id = p.id))
  AND ($5::text IS NULL OR p.display_name ILIKE '%' || $5::text || '%' OR p.domain::text ILIKE '%' || $5::text || '%')
  AND ($6::uuid IS NULL OR p.id < $6::uuid)
ORDER BY p.id DESC LIMIT $7
`

type ListProspectsParams struct {
	TenantID uuid.UUID
	Status   *string
	MinScore *int32
	ListID   *uuid.UUID
	Q        *string
	Before   *uuid.UUID
	Lim      int32
}

type ListProspectsRow struct {
	ID             uuid.UUID
	CompanyID      uuid.UUID
	DisplayName    string
	Domain         *string
	Status         string
	SourceKey      string
	DataQuality    string
	LatestScore    *int32
	LatestCoverage *float64
	CrmCompanyID   *uuid.UUID
	OwnerUserID    *uuid.UUID
	CreatedAt      time.Time
	UpdatedAt      time.Time
}

func (q *Queries) ListProspects(ctx context.Context, arg ListProspectsParams) ([]ListProspectsRow, error) {
	rows, err := q.db.Query(ctx, listProspects,
		arg.TenantID,
		arg.Status,
		arg.MinScore,
		arg.ListID,
		arg.Q,
		arg.Before,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListProspectsRow
	for rows.Next() {
		var i ListProspectsRow
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.DisplayName,
			&i.Domain,
			&i.Status,
			&i.SourceKey,
			&i.DataQuality,
			&i.LatestScore,
			&i.LatestCoverage,
			&i.CrmCompanyID,
			&i.OwnerUserID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

